def is_prime(k):
    """Checks if an integer k is prime."""
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

def find_prime_pair(gap):
    """Searches for n such that n and n + gap are both prime."""
    # We search up to a reasonable limit for computational feasibility.
    # If the answer is small, we will find it quickly.
    limit = 100000 

    # Since we are looking for n such that d(n)=0, n must be prime.
    for n in range(2, limit):
        if is_prime(n):
            n_plus_gap = n + gap
            if is_prime(n_plus_gap):
                return n, n_plus_gap
    return None

